// Types of NodaTime's public API listing, generated by tools/NodaJs.Tools (data api) into nodatime-api.generated.ts.

export interface ApiType {
  /** noda-js name (nested types flattened: "ZoneEqualityComparer+Options" → "ZoneEqualityComparerOptions"). */
  readonly name: string;
  readonly fullName: string;
  readonly kind: "class" | "struct" | "interface" | "enum" | "delegate" | "static class";
  readonly members: readonly ApiMember[];
}

export interface ApiMember {
  /** noda-js name (camelCase; operators keep their C# metadata name, e.g. "op_Addition"). */
  readonly name: string;
  readonly csName: string;
  readonly kind: "constructor" | "property" | "field" | "const" | "method" | "operator" | "indexer";
  readonly isStatic: boolean;
  readonly signatures: readonly string[];
  /** Every overload involves .NET-only types (DateTime, TimeSpan, TimeZoneInfo, XML, ...). */
  readonly bclInterop?: true;
}
